revoke all on function public.cc_delivery_report(date, date)            from public, anon;
revoke all on function public.cc_order_delivery_of(uuid)                from public, anon;
grant execute on function public.cc_set_phone(uuid, text)               to authenticated;
grant execute on function public.cc_list_phones()                       to authenticated;
grant execute on function public.cc_driver_orders()                     to authenticated;
grant execute on function public.cc_driver_take()                       to authenticated;
grant execute on function public.cc_assign_driver(uuid, uuid)           to authenticated;
grant execute on function public.cc_driver_delivered(uuid, text, double precision, double precision, double precision) to authenticated;
grant execute on function public.cc_driver_returned(double precision, double precision, double precision) to authenticated;
grant execute on function public.cc_branch_place()                      to authenticated;
grant execute on function public.cc_set_branch_place(double precision, double precision) to authenticated;
grant execute on function public.cc_admin_drivers()                     to authenticated;
grant execute on function public.cc_new_driver_link(uuid)               to authenticated;
grant execute on function public.cc_admin_update_driver(uuid, text, text, boolean) to authenticated;
do $$ begin
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    execute 'grant execute on function public.cc_driver_setup(uuid, text, text) to service_role';
    execute 'grant execute on function public.cc_driver_by_link(text) to service_role';
    execute 'grant execute on function public.cc_new_driver_link(uuid) to service_role';
  end if;
end $$;
grant execute on function public.cc_admin_delivery(uuid, text, uuid)    to authenticated;
grant execute on function public.cc_list_drivers()                      to authenticated;
grant execute on function public.cc_prep_deliveries()                   to authenticated;
grant execute on function public.cc_delivery_report(date, date)         to authenticated;
grant execute on function public.cc_order_delivery_of(uuid)             to authenticated;

-- ---------------------------------------------------------------------
-- «الطيارين دلوقتي» (admin): each driver's LAST place, sent by his screen about once a minute
-- ONLY while he has orders out (between «خرجت» and «رجعت الفرع»). A web page stops sending when
-- he locks the phone — the admin then sees «آخر مكان من 15 دقيقة». One row per driver, no trail.
-- ---------------------------------------------------------------------
create table if not exists public.cc_driver_location (
  user_id    uuid primary key references auth.users(id),
  lat        double precision not null,
  lng        double precision not null,
  accuracy_m double precision,
  at         timestamptz not null default now()
);
alter table public.cc_driver_location enable row level security;
revoke all on public.cc_driver_location from anon, authenticated, public;

-- The driver's screen: his place now. Kept only while he is out; otherwise ignored (false).
create or replace function public.cc_driver_ping(p_lat double precision, p_lng double precision, p_accuracy double precision)
returns boolean
language plpgsql security definer
set search_path = ''
as $$
declare
  v_me public.cc_staff := public.cc_require_driver();
begin
  if p_lat is null or p_lng is null or p_lat not between -90 and 90 or p_lng not between -180 and 180 then
    return false;
  end if;
  if not exists (select 1 from public.cc_orders o left join public.cc_order_delivery d on d.order_id = o.id
                  where o.driver_user_id = v_me.user_id and o.stage = 'out' and d.returned_at is null
                    and o.out_at > now() - interval '1 day') then
    return false;                                   -- not on a trip: his place is not kept
  end if;
  insert into public.cc_driver_location (user_id, lat, lng, accuracy_m, at)
  values (v_me.user_id, p_lat, p_lng, p_accuracy, now())
  on conflict (user_id) do update
     set lat = excluded.lat, lng = excluded.lng, accuracy_m = excluded.accuracy_m, at = excluded.at
   where public.cc_driver_location.at < now() - interval '15 seconds';   -- at most every 15 s
  return true;
end;
$$;

-- Admin: the drivers out now — orders with him, delivered, when he left, and his last place.
create or replace function public.cc_drivers_now()
returns table (user_id uuid, name text, phone text, orders integer, delivered integer, out_at timestamptz,
               lat double precision, lng double precision, accuracy_m double precision, seen_at timestamptz)
language plpgsql stable security definer
set search_path = ''
as $$
begin
  if not public.cc_is_admin() then
    raise exception 'للأدمن بس' using errcode = '42501';
  end if;
  return query
    select s.user_id, s.display_name, s.phone, count(*)::integer, count(d.delivered_at)::integer, min(o.out_at),
           -- a place from an earlier trip does not count
           case when l.at >= min(o.out_at) then l.lat end, case when l.at >= min(o.out_at) then l.lng end,
           case when l.at >= min(o.out_at) then l.accuracy_m end,
           case when l.at >= min(o.out_at) then l.at end
      from public.cc_orders o
      join public.cc_staff s on s.user_id = o.driver_user_id
      left join public.cc_order_delivery d on d.order_id = o.id
      left join public.cc_driver_location l on l.user_id = o.driver_user_id
     where o.stage = 'out' and o.status <> 'cancelled' and d.returned_at is null
       and o.out_at > now() - interval '1 day'
     group by s.user_id, s.display_name, s.phone, l.lat, l.lng, l.accuracy_m, l.at
     order by min(o.out_at);
end;
$$;

revoke all on function public.cc_driver_ping(double precision, double precision, double precision) from public, anon;
revoke all on function public.cc_drivers_now()                           from public, anon;
grant execute on function public.cc_driver_ping(double precision, double precision, double precision) to authenticated;
grant execute on function public.cc_drivers_now()                        to authenticated;

-- ===== 19_driver_dashboard.sql =====
-- =====================================================================
--  Abu El Fadl Call Center — «لوحة الطيارين» (admin dashboard)
--
--  CONFIRMED: per driver and per area — orders, the money of the orders (total and the
--  delivery fee), the estimated kilometres (from the branch to each delivery place and back,
--  worked out on the page), and the delivery speed.
--  CALL-CENTER ONLY, READ ONLY: the delivery report also returns each order's total and
--  delivery fee. No table changes. Safe to re-run.
-- =====================================================================

create or replace function public.cc_delivery_report(p_from date, p_to date)
returns setof jsonb
language plpgsql stable security definer
set search_path = ''
as $$
declare
  v_from timestamptz := (p_from::timestamp) at time zone 'Africa/Cairo';
  v_to   timestamptz := ((p_to + 1)::timestamp) at time zone 'Africa/Cairo';
begin
  if not public.cc_is_admin() then
    raise exception 'للأدمن بس' using errcode = '42501';
  end if;
  if p_to < p_from or p_to - p_from > 62 then
    raise exception 'اختار فترة لحد شهرين' using errcode = '22023', hint = 'period';
  end if;
  return query
    select jsonb_build_object(
      'id', o.id, 'order_no', o.order_no, 'created_at', o.created_at, 'area_name', o.area_name,
      'at_cashier_at', o.at_cashier_at, 'assigned_at', o.assigned_at, 'out_at', o.out_at, 'out_by_admin', o.out_by_admin,
      'driver_user_id', o.driver_user_id, 'driver', o.driver,
      'trip_id', o.trip_id, 'trip_seq', o.trip_seq, 'trip_size', o.trip_size,
      'delivered_at', d.delivered_at, 'delivered_admin', coalesce(d.delivered_admin, false),
      'photo_path', d.photo_path, 'lat', d.lat, 'lng', d.lng, 'accuracy_m', d.accuracy_m,
      'returned_at', d.returned_at, 'returned_admin', coalesce(d.returned_admin, false), 'returned_by_name', d.returned_by_name,
      'returned_lat', d.returned_lat, 'returned_lng', d.returned_lng, 'returned_distance_m', d.returned_distance_m,
      'returned_far', d.returned_far,
      'total', o.total, 'delivery_fee', o.delivery_fee)
      from public.cc_orders o left join public.cc_order_delivery d on d.order_id = o.id
     where o.out_at >= v_from and o.out_at < v_to and o.status <> 'cancelled'
     order by o.out_at desc, o.trip_seq;
end;
$$;
revoke all on function public.cc_delivery_report(date, date) from public, anon;
grant execute on function public.cc_delivery_report(date, date) to authenticated;

commit;
